/*
 * NeoPixel 8x8 Matrix Rainbow Pattern
 * 
 * Displays a scrolling rainbow gradient on the
 * 8x8 WS2812B NeoPixel matrix.
 *
 * Wiring:
 *   Matrix 5V  → Arduino 5V
 *   Matrix GND → Arduino GND
 *   Matrix DIN → Arduino D6
 */

#include <Adafruit_NeoPixel.h>

#define MATRIX_PIN   6
#define MATRIX_SIZE  64

Adafruit_NeoPixel matrix = Adafruit_NeoPixel(MATRIX_SIZE, MATRIX_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  Serial.begin(115200);
  Serial.println("8x8 NeoPixel Matrix - Rainbow");
  matrix.begin();
  matrix.setBrightness(80);
  matrix.show();
}

void loop() {
  static uint16_t hueOffset = 0;
  
  for (int i = 0; i < MATRIX_SIZE; i++) {
    int row = i / 8;
    int col = i % 8;
    uint16_t hue = (hueOffset + (row + col) * 500) % 65536;
    matrix.setPixelColor(i, matrix.ColorHSV(hue, 255, 255));
  }
  
  matrix.show();
  hueOffset += 256;
  delay(50);
}
